<template>
  <div class="errPage-container">
    <div class="header">
      <el-button icon="el-icon-arrow-left" class="pan-back-btn" @click="back"
        >返回</el-button
      >
    </div>
    <div class="body">
      <h1 class="text-jumbo text-ginormous">Oops! Internal Error</h1>
      <img :src="errGif" />
    </div>
  </div>
</template>

<script>

export default {
  // eslint-disable-next-line vue/multi-word-component-names
  name: 'PageServiceError',
  data() {
    return {
      errGif: require('@/assets/500_images/500.png'),
      dialogVisible: false,
    }
  },
  methods: {
    back() {
      if (this.$route.query.noGoBack) {
        this.$router.push({ path: '/' })
      } else {
        this.$router.go(-1)
      }
    },
  },
}
</script>

